import{_ as a,c as o,o as e,ag as r}from"./chunks/framework._xRlcm3f.js";const p=JSON.parse('{"title":"博客园配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/metaweblog-cnblogs.md","filePath":"platforms/metaweblog-cnblogs.md","lastUpdated":1790228279000}'),l={name:"platforms/metaweblog-cnblogs.md"};function d(n,t,i,s,c,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="博客园配置指南" tabindex="-1">博客园配置指南 <a class="header-anchor" href="#博客园配置指南" aria-label="Permalink to &quot;博客园配置指南&quot;">​</a></h1><blockquote><p>TODO：待替换真实帮助文档链接（当前 helpUrl 指向的短链需用户确认）。</p></blockquote><p>博客园通过 <strong>MetaWeblog XML-RPC</strong> 发布。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个博客园账号。</li><li>一个 <strong>API Token</strong>（不是登录密码！）。</li></ol><h2 id="二、获取-api-token" tabindex="-1">二、获取 API Token <a class="header-anchor" href="#二、获取-api-token" aria-label="Permalink to &quot;二、获取 API Token&quot;">​</a></h2><ol><li>登录博客园后台 → 设置 → 开放 API（或「开放接口」）。</li><li>生成并复制 Token。</li></ol><h2 id="三、在插件里配置" tabindex="-1">三、在插件里配置 <a class="header-anchor" href="#三、在插件里配置" aria-label="Permalink to &quot;三、在插件里配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>你的博客首页，如 <code>https://www.cnblogs.com/你的用户名</code></td></tr><tr><td>API 地址</td><td><code>https://rpc.cnblogs.com/metaweblog/你的博客名</code></td></tr><tr><td>用户名</td><td>博客园登录用户名</td></tr><tr><td>鉴权 Token</td><td>上面生成的 <strong>API Token</strong>（不是登录密码）</td></tr><tr><td>预览规则</td><td>查看文章链接模板，默认 <code>/[userid]/p/[postid].html</code></td></tr><tr><td>发布格式</td><td>默认 Markdown</td></tr><tr><td>图床</td><td>默认「当前平台」（博客园内置）；需要时可选「PicGo 强烈推荐」</td></tr></tbody></table><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证并保存」，通过后账号状态变「运行中」。</li><li>快速发布 → 选博客园 → 发布。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>提示「用户名或密码错误」</strong>：确认用的是 API Token 而非登录密码。</li><li><strong>图片上传失败</strong>：默认「当前平台」即可（博客园内置）；需要时可选「PicGo 强烈推荐」并先在设置里配置好 PicGo。</li></ul>',13)])])}const m=a(l,[["render",d]]);export{p as __pageData,m as default};
